INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-05', 'npl-season-3-format-playoff-structure-explained', 'NPL Season 3 Format Explained: Group Stage, Playoffs & Points Table', 'A complete guide to how Nepal Premier League Season 3 works — group stage format, how the points table operates, and the four-team playoff structure.',
  '["Nepal Premier League Season 3 uses a round-robin group stage followed by a four-team playoff. Here is a complete breakdown of how the competition works.","In the group stage, all eight teams play each other in a round-robin format. Each match awards 2 points to the winning team and 0 to the losing team. If a match is tied or has no result, each team receives 1 point. Net Run Rate (NRR) is used to separate teams level on points.","After 28 group-stage matches, the top four teams on the points table qualify for the playoffs. The four-team playoff follows the IPL-style format: Qualifier 1 (1st vs 2nd, winner goes directly to the final), Eliminator (3rd vs 4th, loser is eliminated), Qualifier 2 (Qualifier 1 loser vs Eliminator winner), and the Final.","The Final is scheduled for 5 Mangsir 2083 BS (21 November 2026) at TU International Cricket Stadium, Kirtipur.","All 32 matches — 28 group stage plus 4 playoff — are played at TU International Cricket Stadium. This single-venue format ensures consistent conditions and concentrated fan attendance.","NPL Hub Nepal provides a live points table page that will be updated throughout the tournament as results are confirmed."]'::jsonb,
  'Tournament', 'published', TRUE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '4 min read', '{}', 'Cricket Association of Nepal / NPL Hub Nepal', NULL,
  '2026-09-15T10:00:00+05:45', '2026-09-15T10:00:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, excerpt = EXCLUDED.excerpt,
