INSERT INTO public.news_articles (
  id, slug, title, excerpt, content, category, status, featured,
  image_url, author, author_role, read_time, tags, source, source_url,
  published_at, updated_at
) VALUES (
  'article-06', 'npl-season-3-eight-franchise-teams-overview', 'All 8 NPL Season 3 Franchise Teams: Regions, Captains & Squad Status', 'An independent overview of all eight Nepal Premier League Season 3 franchise teams, their regional identities, confirmed captains, and current squad status.',
  '["Nepal Premier League Season 3 features eight franchise teams representing different regions of Nepal. Here is an overview of each team based on publicly available information.","Kathmandu Gorkhas represent the capital, Kathmandu. Captain: Rohit Paudel (confirmed). The team is one of the most-watched franchises given its capital city base.","Biratnagar Kings represent the Koshi Province. Captain: Aasif Sheikh (confirmed). Biratnagar is Nepal''s second-largest city and an important cricket hub in the eastern region.","Janakpur Bolts represent Madhesh Province. Captain: Dipendra Singh Airee (confirmed). Dipendra is one of Nepal''s most prominent T20 cricketers.","Pokhara Avengers represent Gandaki Province. Captain: Kushal Malla (confirmed). Pokhara is Nepal''s second-largest city and a tourism centre.","Chitwan Rhinos represent Bagmati Province (southern). Squad and captain details were not officially confirmed at time of writing.","Lumbini Lions represent Lumbini Province. Captain and full squad not officially confirmed at time of writing.","Karnali Yaks represent Karnali Province. Squad and captain details were not officially confirmed at time of writing.","Sudurpaschim Royals represent Sudurpashchim Province. Captain and full squad not officially confirmed at time of writing.","NPL Hub Nepal will update all team profile pages as official squad and captain announcements are made by CAN and the respective franchise teams."]'::jsonb,
  'Teams', 'published', FALSE,
  NULL, 'NPL Hub Nepal Editorial',
  'Editorial', '5 min read', '{}', 'NPL Hub Nepal', NULL,
  '2026-09-10T10:00:00+05:45', '2026-09-10T10:00:00+05:45'
) ON CONFLICT (id) DO UPDATE SET
